use crate::{Arity, FUNCTIONS, Field, Function, NAMESPACES, Parameter, VERSION, record};

/// The formatter's line width, with a tab as wide as four spaces, so the file is already formatted when written.
const WIDTH: usize = 120;
const TAB_WIDTH: usize = 4;

/// The text of the runtime's `src/emit/abi.d.ts`. It is a declaration file because a `.ts` file compiles to a Luau
/// module even when it holds only types, which would change the runtime's output.
pub fn declaration() -> String {
    let mut out = format!(
        "\
// Generated by `cargo xtask abi` from crates/abi. Do not edit.
//
// Version {VERSION} of the ABI between Crucible's transform and this runtime: every call compiled code makes into the emit
// entry. emit/index.ts must satisfy `Abi`, and `Arguments` must satisfy its functions' `ParametersOf`, so a change on
// either side that breaks those calls fails the type check. `Passed` is a value the compiler passes on without
// building it, such as a game's own value or what another call returned, so only its position is checked. `Check` is
// what the runtime calls with a behaviour attribute's value. `Schema` is a wire schema node, which compiled code only
// passes on, so only that it is a table is checked.

type Passed = never;

type Check = (value: unknown) => boolean;

type Schema = object;

type Literal = string | number | boolean;

type Dependency = string | {{ readonly {all}: string }};
",
        all = record::ALL,
    );
    interface(&mut out, "AttributeRecord", None, &[record::ATTRIBUTE]);
    interface(&mut out, "SubsystemRecord", Some(record::SUBSYSTEM), &[record::CLASS]);
    interface(&mut out, "BehaviourRecord", Some(record::BEHAVIOUR), &[record::CLASS, record::BEHAVIOUR_FIELDS]);
    out.push_str("\ntype ClassRecord = SubsystemRecord | BehaviourRecord;\n\nexport interface Abi {\n");
    for function in FUNCTIONS {
        member(&mut out, 1, function, "unknown");
    }
    for namespace in NAMESPACES {
        out.push_str(&format!("\treadonly {}: {{\n", namespace.name));
        for value in namespace.values {
            out.push_str(&format!("\t\treadonly {value}: {};\n", namespace.ty));
        }
        for function in namespace.functions {
            member(&mut out, 2, function, namespace.ty);
        }
        out.push_str("\t};\n");
    }
    out.push_str("}\n\n/** Every argument list a call may pass, which the runtime's function must take. */\n");
    out.push_str("export interface Arguments {\n");
    for function in FUNCTIONS {
        arguments(&mut out, 1, function);
    }
    for namespace in NAMESPACES {
        out.push_str(&format!("\treadonly {}: {{\n", namespace.name));
        for function in namespace.functions {
            arguments(&mut out, 2, function);
        }
        out.push_str("\t};\n");
    }
    out.push_str(
        "}

/** The parameter lists of the functions in `M` that `A` names, without their types. */
export type ParametersOf<M, A = Arguments> = {
\treadonly [K in keyof A & keyof M]: M[K] extends (...args: infer P) => unknown
\t\t? { [I in keyof P]: unknown }
\t\t: ParametersOf<M[K], A[K]>;
};
",
    );
    out
}

fn arguments(out: &mut String, depth: usize, function: &Function) {
    let elements: Vec<String> = function.parameters.iter().map(|p| parameter(p, "unknown")).collect();
    list(out, depth, &format!("readonly {}: ", function.name), ("[", "];"), &elements);
}

fn interface(out: &mut String, name: &str, kind: Option<&str>, fields: &[&[Field]]) {
    out.push_str(&format!("\ninterface {name} {{\n"));
    if let Some(kind) = kind {
        out.push_str(&format!("\treadonly {}: \"{kind}\";\n", record::KIND));
    }
    for field in fields.iter().copied().flatten() {
        let mark = if field.optional { "?" } else { "" };
        out.push_str(&format!("\treadonly {}{mark}: {};\n", field.name, field.ty));
    }
    out.push_str("}\n");
}

/// A function as a property, not a method, so its parameters are checked contravariantly. A top-level function returns
/// `unknown`, because compiled code only passes its result on, and a namespace's function returns the namespace's type.
fn member(out: &mut String, depth: usize, function: &Function, result: &str) {
    let parameters: Vec<String> = function.parameters.iter().map(|p| parameter(p, p.ty)).collect();
    list(out, depth, &format!("readonly {}: ", function.name), ("(", &format!(") => {result};")), &parameters);
}

fn parameter(parameter: &Parameter, ty: &str) -> String {
    match parameter.arity {
        Arity::Required => format!("{}: {ty}", parameter.name),
        Arity::Optional => format!("{}?: {ty}", parameter.name),
        Arity::Rest => format!("...{}: {ty}[]", parameter.name),
    }
}

/// One line when it fits, and otherwise one item per line, as the formatter breaks it.
fn list(out: &mut String, depth: usize, head: &str, (open, close): (&str, &str), items: &[String]) {
    let indent = "\t".repeat(depth);
    let line = format!("{indent}{head}{open}{}{close}", items.join(", "));
    if width(&line) <= WIDTH {
        out.push_str(&line);
        out.push('\n');
        return;
    }
    out.push_str(&format!("{indent}{head}{open}\n"));
    for item in items {
        out.push_str(&format!("{indent}\t{item},\n"));
    }
    out.push_str(&format!("{indent}{close}\n"));
}

fn width(line: &str) -> usize {
    line.chars().map(|c| if c == '\t' { TAB_WIDTH } else { 1 }).sum()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_line_fits_the_formatter_width() {
        for line in declaration().lines() {
            assert!(width(line) <= WIDTH, "too wide: {line}");
        }
    }

    #[test]
    fn a_long_signature_puts_each_parameter_on_its_own_line() {
        let text = declaration();
        assert!(text.contains("\treadonly profileStore: (\n\t\tname: string,\n"), "{text}");
        assert!(text.contains("\t\tserverOnlyPaths: readonly (readonly string[])[],\n\t) => unknown;\n"), "{text}");
        assert!(text.contains("\t\treadonly union: (...checks: Check[]) => Check;\n"), "{text}");
    }
}
